// This includes information about the last frame read, current stream state,
// configuration flags, and buffer settings. Useful for debugging frame processing issues.
func (fr *Framer) Dump() string {
	var lastFrameType string
	var lastFrameStreamID uint32
	if fr.lastFrame != nil {
		fh := fr.lastFrame.Header()
		lastFrameType = fh.Type.String()
		lastFrameStreamID = fh.StreamID
	} else {
		lastFrameType = "none"
