func readAndCheckFrameHeader(r netpoll.Reader) (http2.FrameHeader, error) {
	buf, err := r.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, err
	}

	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
	}

	// Validation: check frame length doesn't exceed max frame size
	if fh.Length > http2MaxFrameLen {
		return fh, http2.ConnectionError(http2.ErrCodeFrameSize)
	}

	// Validation: certain frame types must have specific stream IDs
	switch fh.Type {
	case http2.FrameSettings, http2.FramePing, http2.FrameGoAway:
		// These frames must have stream ID 0
		if fh.StreamID != 0 {
			return fh, http2.ConnectionError(http2.ErrCodeProtocol)
		}
	case http2.FrameWindowUpdate:
		// Window update can be on stream 0 or specific stream, but not invalid stream ID
		// Stream ID with high bit set is invalid (already masked above)
	default:
		// Most other frames require non-zero stream ID
		if fh.StreamID == 0 && fh.Type != http2.FramePriority {
			return fh, http2.ConnectionError(http2.ErrCodeProtocol)
